// Site data contract, schema_version 1. Generated by playbook/export.py.
// Source of truth: DESIGN.md, "Site data contract". Do not edit without bumping schema_version.

export type Side = "T" | "CT";
export type Lane = "T_SPAWN" | "A" | "MID" | "B" | "CT_SPAWN" | "OTHER";
export type GrenadeType = "smoke" | "flashbang" | "molotov" | "he";
export type Technique = "jump" | "run" | "crouch" | "walk" | "stand";
export type BuyType = "pistol" | "eco" | "force" | "full";
export type ExecuteTiming = "fast" | "default_then_execute" | "late" | "no_clear_execute";
export type Role = "awper" | "a_anchor" | "b_anchor" | "mid_ct" | "lurker" | "entry" | "support";

/** A ranked value with its sample: setups, plant sites, execute timing, ... */
export interface Ranked<V = string> {
  value: V;
  rounds: number;
  share: number | null;
  won: number;
  win_rate: number | null;
}

export interface SiteIndex {
  schema_version: 1;
  generated_at: string;
  min_matches_reliable: number;
  data_source: string;
  maps: {
    map: string;
    display_name: string;
    n_matches: number;
    teams: string[]; // team slugs
    n_players: number;
    n_lineups: number;
  }[];
}

export interface MapMeta {
  map: string;
  display_name: string;
  /** radar_x = (x - pos_x) / scale ; radar_y = (pos_y - y) / scale, on a 1024x1024 image */
  radar: { pos_x: number; pos_y: number; scale: number; lower_level_max_z?: number };
  radar_image: string;
  regions: Record<string, Lane>; // region -> lane
  callouts: Record<string, string>; // callout -> region
}

export interface TeamSummary {
  team: string;
  slug: string;
  n_matches: number;
  low_sample: boolean;
  win_rate_T: number | null;
  win_rate_CT: number | null;
}

interface SideCommon {
  rounds: number;
  won: number;
  win_rate: number | null;
  gun_rounds: number;
  opening_win_rate: number | null;
  avg_first_kill_s: number | null;
  avg_util_per_round: number | null;
  avg_early_util: number | null;
  /** lane shape of living players, e.g. "A2 M2 B1" (S = T spawn, C = CT spawn), gun rounds only */
  setups_15s: Ranked[];
  setups_30s: Ranked[];
}

export interface TSide extends SideCommon {
  plant_sites: Ranked<"A" | "B" | "none">[];
  avg_plant_t_s: number | null;
  execute_timing: Ranked<ExecuteTiming>[];
  execute_lane: Ranked<Lane>[];
  avg_execute_start_s: number | null;
}

export interface CTSide extends SideCommon {
  plants_against: number;
  retakes_won: number;
  retake_win_rate: number | null;
  plants_against_by_site: Ranked<"A" | "B">[];
  stack_rate_15s: number | null;
}

export interface TeamProfile {
  team: string;
  slug: string;
  map: string;
  n_matches: number;
  low_sample: boolean;
  matches: {
    demo_id: string;
    hltv_match_id: number | null;
    opponent: string | null;
    score_for: number;
    score_against: number;
  }[];
  sides: { T: TSide; CT: CTSide };
  economy: { side: Side; buy_type: BuyType; rounds: number; won: number; win_rate: number | null }[];
}

export interface Share {
  value: string;
  share: number | null;
}

export interface RoleHint {
  role: Role;
  metric: string;
  value: number | null;
  team_median?: number;
}

export interface PlayerProfile {
  steamid: string;
  name: string;
  team: string;
  n_matches: number;
  rounds: { total: number; T: number; CT: number };
  kpr: number | null;
  dpr: number | null;
  hs_pct: number | null;
  opening_kills_pr: number | null;
  opening_deaths_pr: number | null;
  opening_success: number | null;
  traded_death_rate: number | null;
  awp_share: number | null;
  util_pr: number | null;
  T: { avg_dist_to_team_30s: number | null; first_into_site_rate: number | null; lanes_15s: Share[]; places_30s: Share[] };
  CT: { lanes_15s: Share[]; places_30s: Share[] };
  role_hints: RoleHint[];
}

export interface Lineup {
  id: string;
  side: Side;
  type: GrenadeType;
  throw_place: string | null;
  land_place: string | null;
  land_region: string | null;
  land_lane: Lane | null;
  n_throws: number;
  n_matches: number;
  teams: string[];
  throwers: string[];
  round_win_rate: number | null;
  median_pop_t_s: number | null;
  technique: Technique;
  jump_share: number | null;
  throw: { x: number; y: number; z: number; pitch: number; yaw: number; radar_x: number; radar_y: number };
  land: { x: number; y: number; z: number; radar_x: number; radar_y: number };
  /** paste into the CS2 console on a practice server (sv_cheats 1) */
  practice_cmd: string;
  example: { demo_id: string; round_num: number; throw_tick: number };
}
